/**
 * Names avoid `message` (Kotlin's `Throwable.message`) and `Protocol` (reserved in Swift).
 */
public enum FfiSyncError {

    
    
    case WrongCode(attemptsLeft: UInt32
    )
    case DifferentVault
    case NoVault
    case Version
    case Expired
    case Stopped
    case Io(detail: String
    )
    case Store(detail: String
    )
    /**
     * Not `Protocol`: Swift can't have a type member with that name.
     */
    case Unexpected
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiSyncError: FfiConverterRustBuffer {
    typealias SwiftType = FfiSyncError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiSyncError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .WrongCode(
            attemptsLeft: try FfiConverterUInt32.read(from: &buf)
            )
        case 2: return .DifferentVault
        case 3: return .NoVault
        case 4: return .Version
        case 5: return .Expired
        case 6: return .Stopped
        case 7: return .Io(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Store(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Unexpected

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiSyncError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .WrongCode(attemptsLeft):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(attemptsLeft, into: &buf)
            
        
        case .DifferentVault:
            writeInt(&buf, Int32(2))
        
        
        case .NoVault:
            writeInt(&buf, Int32(3))
        
        
        case .Version:
            writeInt(&buf, Int32(4))
        
        
        case .Expired:
            writeInt(&buf, Int32(5))
        
        
        case .Stopped:
            writeInt(&buf, Int32(6))
        
        
        case let .Io(detail):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Store(detail):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .Unexpected:
            writeInt(&buf, Int32(9))
        
        }
    }
}


